import { cva, type VariantProps } from "class-variance-authority";
import { InfoIcon } from "lucide-react";
import React from "react";

import { cn, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

const alertVariants = cva(
  "relative grid w-full grid-cols-[0_1fr] items-start gap-y-0.5 rounded-lg border px-4 py-3 text-sm has-[>svg]:grid-cols-[calc(var(--spacing)*4)_1fr] has-[>svg]:gap-x-3 [&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current",
  {
    defaultVariants: {
      variant: "info",
    },
    variants: {
      variant: {
        destructive:
          "!border-destructive/20 bg-destructive/10 text-destructive *:data-[slot=alert-description]:text-destructive/90 [&>href]:text-current [&>svg]:text-current",
        info: "bg-card text-card-foreground",
        success:
          "!border-green-200 dark:!border-green-800/40 bg-green-50 text-green-800 *:data-[slot=alert-description]:text-green-800 dark:bg-green-950/30 dark:text-green-300 dark:*:data-[slot=alert-description]:text-green-300 [&>href]:text-current [&>svg]:text-current",
        warning:
          "!border-blue-200 bg-blue-50 text-blue-800 *:data-[slot=alert-description]:text-blue-800 [&>href]:text-current [&>svg]:text-current",
      },
    },
  }
);
const DEFAULT_ALERT_ICON = <InfoIcon />;

const Alert = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & VariantProps<typeof alertVariants> & SharedProps & { icon?: React.ReactNode }
>(({ className, variant, testId, icon = DEFAULT_ALERT_ICON, children, ...props }, ref) => (
  <div
    className={cn(alertVariants({ variant }), className)}
    data-slot="alert"
    data-testid={testId}
    ref={ref}
    role="alert"
    {...props}
  >
    {icon}
    {children}
  </div>
));

Alert.displayName = "Alert";

const AlertTitle = React.forwardRef<HTMLDivElement, React.ComponentProps<"div"> & SharedProps>(
  ({ className, testId, ...props }, ref) => (
    <div
      className={cn("col-start-2 line-clamp-1 min-h-4 font-medium tracking-tight", className)}
      data-slot="alert-title"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

AlertTitle.displayName = "AlertTitle";

const AlertDescription = React.forwardRef<HTMLDivElement, React.ComponentProps<"div"> & SharedProps>(
  ({ className, testId, ...props }, ref) => (
    <div
      className={cn(
        "col-start-2 grid w-full min-w-0 justify-items-start gap-1 text-muted-foreground text-sm [&_p]:leading-relaxed [&_pre]:w-full",
        className
      )}
      data-slot="alert-description"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

AlertDescription.displayName = "AlertDescription";

export { Alert, AlertDescription, AlertTitle };

import { cva, type VariantProps } from "class-variance-authority";
import type React from "react";

import { Slot } from "@/registry/base-nova/protoform/lib/base-ui-compat";
import { cn, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

const badgeVariants = cva(
  "inline-flex max-w-full shrink-0 items-center justify-center truncate rounded-md border font-medium transition-[color,box-shadow] selection:bg-selected selection:text-selected-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none",
  {
    defaultVariants: {
      size: "md",
      variant: "neutral",
    },
    variants: {
      size: {
        // Large: 32px height (from Figma)
        lg: "h-8 gap-1.5 px-3 py-0 text-sm has-[>svg]:px-2 [&_svg]:size-4",
        // Medium: 24px height (from Figma)
        md: "h-6 gap-1 px-2 py-0 text-xs has-[>svg]:px-1.5 [&_svg]:size-3.5",
        // Small: 20px height (from Figma)
        sm: "h-5 gap-1 px-1.5 py-0 text-[11px] has-[>svg]:px-1 [&_svg]:size-3",
      },
      variant: {
        // === ACCENT (Brand Red - uses theme brand tokens) ===
        accent: "border-transparent bg-brand text-inverse [a&]:hover:bg-surface-brand-hover",
        "accent-inverted": "border-transparent bg-background-brand-subtle text-brand [a&]:hover:bg-brand-alpha-default",
        "accent-outline": "border-outline-brand bg-transparent text-brand [a&]:hover:bg-brand-alpha-subtle",

        // === DESTRUCTIVE/ERROR (Red - semantic tokens) ===
        destructive:
          "border-transparent bg-surface-error text-inverse focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 [a&]:hover:bg-surface-error-hover",
        "destructive-inverted":
          "border-transparent bg-background-error-subtle text-destructive [a&]:hover:bg-destructive-subtle",
        "destructive-outline":
          "border-outline-error bg-transparent text-destructive [a&]:hover:bg-background-error-subtle",

        // === DISABLED (Muted - semantic tokens) ===
        disabled: "cursor-not-allowed border-transparent bg-background-disabled text-disabled",
        "disabled-inverted": "cursor-not-allowed border-transparent bg-surface-subtle text-disabled",
        "disabled-outline": "cursor-not-allowed border-border-strong bg-transparent text-disabled",

        // === INFO (Blue - semantic tokens) ===
        info: "border-transparent bg-surface-informative text-inverse [a&]:hover:bg-surface-informative-hover",
        "info-inverted":
          "border-transparent bg-background-informative-subtle text-info [a&]:hover:bg-background-informative-subtle-hover",
        "info-outline":
          "border-outline-informative bg-transparent text-info [a&]:hover:bg-background-informative-subtle",
        // === NEUTRAL (Grey - semantic tokens) ===
        neutral:
          "border-transparent bg-background-inverse-subtle text-inverse [a&]:hover:bg-background-inverse-subtle-hover",
        "neutral-inverted": "border-transparent bg-surface-subtle [a&]:hover:bg-background-subtle-hover",
        "neutral-outline": "!border-outline-inverse border [a&]:hover:bg-background-subtle-hover",

        // === OUTLINE (generic) ===
        outline: "border-border text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground",

        // === PRIMARY (Indigo) ===
        primary: "border-transparent bg-primary text-inverse [a&]:hover:bg-primary/90",
        "primary-inverted": "border-transparent bg-primary/10 text-primary [a&]:hover:bg-primary/20",
        "primary-outline": "border-primary text-primary [a&]:hover:bg-primary/10",

        // === SECONDARY (Dark Blue) ===
        secondary: "border-transparent bg-secondary text-inverse [a&]:hover:bg-secondary/90",
        "secondary-inverted": "border-transparent bg-secondary/10 text-secondary [a&]:hover:bg-secondary/20",
        "secondary-outline": "border-secondary text-secondary [a&]:hover:bg-secondary/10",

        // === SIMPLE (Light grey - semantic tokens) ===
        simple: "text-secondary [a&]:hover:bg-background-subtle-hover",
        "simple-inverted": "text-secondary [a&]:hover:bg-background-subtle-hover",
        "simple-outline": "!border-outline-inverse border text-secondary [a&]:hover:bg-background-subtle-hover",

        // === SUCCESS (Green - semantic tokens) ===
        success: "border-transparent bg-surface-success text-inverse [a&]:hover:bg-surface-success-hover",
        "success-inverted":
          "border-transparent bg-background-success-subtle text-success [a&]:hover:bg-background-success-subtle-hover",
        "success-outline": "border-outline-success bg-transparent text-success [a&]:hover:bg-background-success-subtle",

        // === WARNING (Yellow/Orange - semantic tokens) ===
        warning: "border-transparent bg-surface-warning text-inverse [a&]:hover:bg-surface-warning-hover",
        "warning-inverted": "border-transparent bg-background-warning-subtle text-warning [a&]:hover:bg-warning-subtle",
        "warning-outline": "border-outline-warning bg-transparent text-warning [a&]:hover:bg-background-warning-subtle",
      },
    },
  }
);

export type BadgeVariant = VariantProps<typeof badgeVariants>["variant"];
export type BadgeSize = VariantProps<typeof badgeVariants>["size"];

function Badge({
  className,
  variant,
  asChild = false,
  testId,
  icon,
  children,
  size,
  ref,
  ...props
}: React.ComponentProps<"span"> &
  SharedProps & {
    asChild?: boolean;
    icon?: React.ReactNode;
    variant?: BadgeVariant;
    size?: BadgeSize;
  }) {
  const Comp = asChild ? Slot : "span";

  // When asChild is used with Slot, we can only pass ONE child element
  // to satisfy React.Children.only(). In asChild mode, users must include
  // icons inside children instead of using the icon prop.
  const renderContent = () => {
    if (asChild) {
      return children;
    }

    // Normal badge mode - can have icon + children
    if (icon && children) {
      return (
        <>
          {icon}
          <span className="truncate">{children}</span>
        </>
      );
    }

    if (icon) {
      return icon;
    }

    if (children) {
      return <span className="truncate">{children}</span>;
    }

    return null;
  };

  return (
    <Comp
      className={cn(badgeVariants({ size, variant }), className)}
      data-slot="badge"
      data-testid={testId}
      ref={ref}
      {...props}
    >
      {renderContent()}
    </Comp>
  );
}

export { Badge, badgeVariants };

"use client";

import { cva, type VariantProps } from "class-variance-authority";
import React, { type ElementType } from "react";

import { useGroup } from "@/components/ui/group";
import { Spinner } from "@/components/ui/spinner";
import { Slot } from "@/registry/base-nova/protoform/lib/base-ui-compat";
import { cn, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

const buttonVariants = cva(
  [
    "group/button inline-flex shrink-0 items-center justify-center",
    "whitespace-nowrap rounded-lg border border-transparent bg-clip-padding font-medium text-sm",
    "select-none outline-none transition-all",
    "cursor-pointer",
    "disabled:pointer-events-none disabled:cursor-not-allowed",
    "disabled:opacity-50",
    "focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50",
    "aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20",
    "dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
    "selection:bg-selected selection:text-selected-foreground",
    "active:not-aria-[haspopup]:translate-y-px",
    '[&_svg:not([class*="size-"])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0',
  ],
  {
    defaultVariants: {
      size: "md",
      variant: "primary",
    },
    variants: {
      size: {
        icon: "size-8 [&_svg]:size-4",
        "icon-lg": "size-9 [&_svg]:size-4",
        "icon-sm": "size-7 [&_svg]:size-3.5",
        "icon-xs": "size-6 [&_svg]:size-3",
        lg: "h-9 gap-1.5 px-2.5 has-[>svg]:px-2 [&_svg]:size-4",
        md: "h-8 gap-1.5 px-2.5 has-[>svg]:px-2 [&_svg]:size-4",
        sm: "h-7 gap-1 px-2.5 text-[0.8rem] has-[>svg]:px-2 [&_svg]:size-3.5",
        xs: "h-6 gap-1 px-2 text-xs has-[>svg]:px-1.5 [&_svg]:size-3",
      },
      variant: {
        accent: [
          "bg-brand text-inverse shadow-xs",
          "hover:bg-surface-brand-hover",
          "active:bg-surface-brand-pressed",
          "disabled:bg-background-disabled disabled:text-disabled",
        ],
        "accent-ghost": [
          "bg-transparent text-brand",
          "hover:bg-surface-brand-subtle hover:text-brand",
          "active:bg-surface-brand-subtle-hover",
          "disabled:text-disabled",
        ],
        "accent-outline": [
          "!border-brand border bg-transparent text-brand shadow-xs",
          "hover:border-outline-brand-hover hover:bg-brand-alpha-subtle",
          "active:border-outline-brand-pressed active:bg-brand-alpha-default",
          "disabled:border-border disabled:text-disabled",
        ],
        // Dashed border variant
        dashed: [
          "!border-primary border-2 border-dashed bg-transparent text-primary",
          "hover:border-primary/80 hover:bg-primary/5",
          "active:bg-primary/10",
          "disabled:border-border disabled:text-disabled",
        ],
        destructive: [
          "bg-destructive text-inverse shadow-xs",
          "hover:bg-surface-error-hover",
          "active:bg-surface-error-pressed",
          "focus-visible:ring-destructive",
          "disabled:bg-background-disabled disabled:text-disabled",
        ],
        "destructive-ghost": [
          "bg-transparent text-destructive",
          "hover:bg-background-error-subtle hover:text-destructive",
          "active:bg-destructive-subtle",
          "focus-visible:ring-destructive",
          "disabled:text-disabled",
        ],
        "destructive-outline": [
          "!border-destructive border bg-transparent text-destructive shadow-xs",
          "hover:border-outline-error-hover hover:bg-destructive-alpha-subtle",
          "active:border-outline-error-pressed active:bg-destructive-alpha-default",
          "focus-visible:ring-destructive",
          "disabled:border-border disabled:text-disabled",
        ],
        ghost: ["bg-transparent text-foreground", "hover:bg-muted hover:text-foreground", "active:bg-muted/80"],
        inverse: [
          "bg-surface-inverse text-secondary shadow-xs",
          "hover:bg-surface-inverse-hover",
          "active:bg-surface-inverse-pressed",
          "disabled:bg-surface-inverse-disabled disabled:text-disabled",
        ],
        "inverse-ghost": [
          "bg-transparent text-inverse-primary",
          "hover:bg-light-alpha-strong",
          "active:bg-light-alpha-stronger",
          "disabled:text-inverse-disabled",
        ],
        "inverse-outline": [
          "!border-inverse-primary border bg-transparent text-inverse-primary shadow-xs",
          "hover:border-transparent hover:bg-light-alpha-strong",
          "active:border-transparent active:bg-light-alpha-stronger",
          "disabled:border-inverse-disabled disabled:text-inverse-disabled",
        ],
        // Link variant
        link: [
          "text-primary underline-offset-4",
          "hover:text-primary/80 hover:underline",
          "active:text-primary/60",
          "disabled:text-disabled disabled:no-underline",
        ],
        outline: [
          "border border-input bg-background text-foreground shadow-xs",
          "hover:bg-muted hover:text-foreground",
          "active:bg-muted/80",
        ],
        primary: [
          "bg-primary text-primary-foreground shadow-xs",
          "hover:bg-primary/90",
          "active:bg-primary/80",
          undefined,
        ],
        secondary: [
          "bg-surface-primary text-inverse shadow-xs",
          "hover:bg-surface-primary-hover",
          "active:bg-surface-primary-pressed",
          "disabled:bg-background-disabled disabled:text-disabled",
        ],
        "secondary-ghost": [
          "bg-transparent text-secondary",
          "hover:bg-surface-secondary-subtle",
          "active:bg-surface-secondary-subtle-hover",
          "disabled:text-disabled",
        ],
        "secondary-outline": [
          "!border-outline-inverse border text-secondary shadow-xs",
          "hover:border-outline-hover hover:bg-secondary-alpha-subtle",
          "active:border-outline-pressed active:bg-secondary-alpha-default",
          "disabled:border-outline-inverse-disabled disabled:text-disabled",
        ],
      },
    },
  }
);

export type ButtonVariants = VariantProps<typeof buttonVariants>;

export type ButtonProps = React.ComponentProps<"button"> &
  ButtonVariants & {
    asChild?: boolean | undefined;
    as?: ElementType | undefined;
    to?: string | undefined;
    icon?: React.ReactNode | undefined;
    /**
     * Renders a centered spinner overlay while keeping the button at its
     * natural width. Also disables interaction and sets aria-busy.
     */
    isLoading?: boolean | undefined;
    // Support anchor element props when as="a"
    href?: string | undefined;
    target?: string | undefined;
    rel?: string | undefined;
  } & SharedProps;

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      testId,
      as,
      to,
      icon,
      isLoading = false,
      disabled,
      children,
      ...props
    },
    ref
  ) => {
    const Comp = as ?? (asChild ? Slot : "button");
    const { attached, position } = useGroup();

    let positionClasses = "rounded-lg";
    if (attached && position === "first") {
      positionClasses = "rounded-r-none rounded-l-lg border-r-0";
    } else if (attached && position === "last") {
      positionClasses = "rounded-r-lg rounded-l-none border-l-0";
    } else if (attached && position === "middle") {
      positionClasses = "rounded-none border-r-0 border-l-0";
    }

    const isDisabled = disabled || isLoading;

    // When asChild is used with Slot, we can only pass ONE child element
    // to satisfy React.Children.only(). In asChild mode, users must include
    // icons inside children instead of using the icon prop.
    const renderContent = () => {
      if (asChild) {
        return children;
      }

      // Normal button mode - can have children + icon prop
      const content = icon ? (
        <>
          {children}
          {icon}
        </>
      ) : (
        children
      );

      if (isLoading) {
        return (
          <>
            <span className="invisible inline-flex items-center justify-center [gap:inherit]">{content}</span>
            <span aria-hidden="true" className="absolute inset-0 flex items-center justify-center">
              <Spinner />
            </span>
          </>
        );
      }

      return content;
    };

    return (
      <Comp
        aria-busy={isLoading || undefined}
        className={cn(
          buttonVariants({ className, size, variant }),
          positionClasses,
          icon && "gap-2",
          isLoading && "relative",
          className
        )}
        data-loading={isLoading || undefined}
        data-slot="button"
        data-testid={testId}
        disabled={isDisabled}
        ref={ref}
        to={to}
        {...props}
      >
        {renderContent()}
      </Comp>
    );
  }
);

Button.displayName = "Button";

export { Button, buttonVariants };

"use client";

import { ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon } from "lucide-react";
import React from "react";
import { type DayButton, DayPicker, getDefaultClassNames } from "react-day-picker";

import { Button, buttonVariants } from "@/components/ui/button";
import { cn, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

function CalendarRoot({
  className,
  rootRef,
  ...props
}: React.ComponentProps<"div"> & { rootRef?: React.Ref<HTMLDivElement> }) {
  return <div className={cn(className)} data-slot="calendar" ref={rootRef} {...props} />;
}

function CalendarChevron({
  className,
  orientation,
  ...props
}: {
  className?: string;
  orientation?: "left" | "right" | "down" | "up";
}) {
  if (orientation === "left") {
    return <ChevronLeftIcon className={cn("size-4", className)} {...props} />;
  }

  if (orientation === "right") {
    return <ChevronRightIcon className={cn("size-4", className)} {...props} />;
  }

  return <ChevronDownIcon className={cn("size-4", className)} {...props} />;
}

function CalendarWeekNumber({ children, ...props }: React.ComponentProps<"td">) {
  return (
    <td {...props}>
      <div className="flex size-(--cell-size) items-center justify-center text-center">{children}</div>
    </td>
  );
}

const CalendarRootWithTestId = React.memo(
  ({ testId, ...props }: React.ComponentProps<typeof CalendarRoot> & { testId?: string | undefined }) => (
    <CalendarRoot {...props} data-testid={testId} />
  )
);

CalendarRootWithTestId.displayName = "CalendarRootWithTestId";

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  buttonVariant = "ghost",
  formatters,
  components,
  testId,
  ...props
}: React.ComponentProps<typeof DayPicker> &
  SharedProps & {
    buttonVariant?: React.ComponentProps<typeof Button>["variant"];
  }) {
  "use no memo";

  const defaultClassNames = getDefaultClassNames();

  const rootComponent = React.useMemo(
    () =>
      Object.assign(
        ({ ref, ...rootProps }: React.ComponentProps<typeof CalendarRoot> & { ref?: React.Ref<HTMLDivElement> }) => (
          <CalendarRootWithTestId {...rootProps} rootRef={ref ?? null} testId={testId} />
        ),
        { displayName: "CalendarRootComponent" }
      ),
    [testId]
  );

  return (
    <DayPicker
      captionLayout={captionLayout}
      className={cn(
        "group/calendar bg-background p-3 [--cell-size:--spacing(8)] [[data-slot=card-content]_&]:bg-transparent [[data-slot=popover-content]_&]:bg-transparent",
        String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
        String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
        className
      )}
      classNames={{
        button_next: cn(
          buttonVariants({ variant: buttonVariant }),
          "size-(--cell-size) select-none p-0 aria-disabled:opacity-50",
          defaultClassNames.button_next
        ),
        button_previous: cn(
          buttonVariants({ variant: buttonVariant }),
          "size-(--cell-size) select-none p-0 aria-disabled:opacity-50",
          defaultClassNames.button_previous
        ),
        caption_label: cn(
          "select-none font-medium",
          captionLayout === "label"
            ? "text-sm"
            : "flex h-8 items-center gap-1 rounded-md pr-1 pl-2 text-sm [&>svg]:size-3.5 [&>svg]:text-muted-foreground",
          defaultClassNames.caption_label
        ),
        day: cn(
          "group/day relative aspect-square size-full select-none p-0 text-center [&:first-child[data-selected=true]_button]:rounded-l-md [&:last-child[data-selected=true]_button]:rounded-r-md",
          defaultClassNames.day
        ),
        disabled: cn("text-muted-foreground opacity-50", defaultClassNames.disabled),
        dropdown: cn("absolute inset-0 opacity-0", defaultClassNames.dropdown),
        dropdown_root: cn(
          "!border-input relative rounded-md border shadow-xs has-focus:border-ring has-focus:ring-[3px] has-focus:ring-ring/50",
          defaultClassNames.dropdown_root
        ),
        dropdowns: cn(
          "flex h-(--cell-size) w-full items-center justify-center gap-1.5 font-medium text-sm",
          defaultClassNames.dropdowns
        ),
        hidden: cn("invisible", defaultClassNames.hidden),
        month: cn("flex w-full flex-col gap-4", defaultClassNames.month),
        month_caption: cn(
          "flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)",
          defaultClassNames.month_caption
        ),
        months: cn("relative flex flex-col gap-4 md:flex-row", defaultClassNames.months),
        nav: cn("absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1", defaultClassNames.nav),
        outside: cn("text-muted-foreground aria-selected:text-muted-foreground", defaultClassNames.outside),
        range_end: cn("rounded-r-md bg-accent", defaultClassNames.range_end),
        range_middle: cn("rounded-none", defaultClassNames.range_middle),
        range_start: cn("rounded-l-md bg-accent", defaultClassNames.range_start),
        root: cn("w-fit", defaultClassNames.root),
        today: cn(
          "rounded-md bg-accent text-accent-foreground data-[selected=true]:rounded-none",
          defaultClassNames.today
        ),
        week: cn("mt-2 flex w-full", defaultClassNames.week),
        week_number: cn("select-none text-[0.8rem] text-muted-foreground", defaultClassNames.week_number),
        week_number_header: cn("w-(--cell-size) select-none", defaultClassNames.week_number_header),
        weekday: cn(
          "flex-1 select-none rounded-md font-normal text-[0.8rem] text-muted-foreground",
          defaultClassNames.weekday
        ),
        weekdays: cn("flex", defaultClassNames.weekdays),
        ...classNames,
      }}
      components={{
        Chevron: CalendarChevron,
        DayButton: CalendarDayButton,
        Root: rootComponent,
        WeekNumber: CalendarWeekNumber,
        ...components,
      }}
      formatters={{
        formatMonthDropdown: (date) => date.toLocaleString("default", { month: "short" }),
        ...formatters,
      }}
      showOutsideDays={showOutsideDays}
      {...props}
    />
  );
}

