/** Resolve a controlled value to its display label. */
export const resolveLabel = (options: readonly ComboboxOption[], value: string): string => {
  const opt = options.find((o) => o.value === value);
  return opt?.label ?? value;
};

/** Filter options by a case-insensitive query against label and value. */
export const filterOptions = (
  options: readonly ComboboxOption[],
  query: string,
  selectedLabel: string
): ComboboxOption[] => {
  if (!query) {
    return [...options];
  }
  // If input matches the selected option's label exactly, show all options
  if (query === selectedLabel && selectedLabel) {
    return [...options];
  }
  const lowerQuery = query.toLowerCase();
  return options.filter(
    (option) => option.label.toLowerCase().includes(lowerQuery) || option.value.toLowerCase().includes(lowerQuery)
  );
};

/** Group options by their `group` field, preserving insertion order. Returns undefined if no groups exist. */
export const groupOptions = (options: readonly ComboboxOption[]): GroupedOptions[] | undefined => {
  if (!options.some((option) => option.group)) {
    return;
  }

  const groups = new Map<string, GroupedOptions>();
  for (const option of options) {
    const groupKey = option.group || "";
    const existing = groups.get(groupKey);
    if (existing) {
      groups.set(groupKey, { ...existing, options: [...existing.options, option] });
    } else {
      groups.set(groupKey, {
        heading: groupKey,
        options: [option],
        testId: option.groupTestId,
      });
    }
  }
  return Array.from(groups.values());
};

/** Build the flat list of navigable cmdk values for keyboard navigation. */
export const getNavigableValues = (
  filteredOptions: readonly ComboboxOption[],
  canCreate: boolean,
  inputValue: string
): string[] => {
  const base = filteredOptions.map((opt) => opt.label);
  return canCreate ? [...base, `${CREATE_ITEM_PREFIX}${inputValue}`] : base;
};

/** Compute the next highlight value with circular wrapping. */
export const computeNextHighlight = (
  navigableValues: readonly string[],
  currentHighlight: string,
  direction: 1 | -1
): string => {
  if (navigableValues.length === 0) {
    return "";
  }
  const currentIndex = navigableValues.findIndex((v) => v.toLowerCase() === currentHighlight.toLowerCase());
  let nextIndex: number;
  if (currentIndex === -1) {
    nextIndex = direction === 1 ? 0 : navigableValues.length - 1;
  } else {
    nextIndex = currentIndex + direction;
    if (nextIndex < 0) {
      nextIndex = navigableValues.length - 1;
    }
    if (nextIndex >= navigableValues.length) {
      nextIndex = 0;
    }
  }
  return navigableValues[nextIndex] ?? currentHighlight;
};

/** Find the first matching option for a query string (used for auto-highlight on type). */
export const findFirstMatch = (options: readonly ComboboxOption[], query: string): string => {
  if (!query) {
    return "";
  }
  const lowerQuery = query.toLowerCase();
  const match = options.find(
    (opt) => opt.label.toLowerCase().includes(lowerQuery) || opt.value.toLowerCase().includes(lowerQuery)
  );
  return match?.label ?? match?.value ?? "";
};

"use client";

import { useCommandState } from "cmdk";
import { Check, ChevronsUpDown, Plus, Search, X } from "lucide-react";
import type React from "react";
import { memo, useCallback, useEffect, useId, useMemo, useReducer, useRef } from "react";

import { Button } from "@/components/ui/button";
import { Command, CommandEmpty, CommandGroup, CommandItem, CommandList } from "@/components/ui/command";
import { Input, InputEnd, InputStart } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Spinner } from "@/components/ui/spinner";
import {
  cn,
  type PortalContentProps,
  type PortalRootProps,
  type SharedProps,
} from "@/registry/base-nova/protoform/lib/utils";

import {
  CREATE_ITEM_PREFIX,
  computeNextHighlight,
  filterOptions,
  findFirstMatch,
  getNavigableValues,
  groupOptions,
  resolveLabel,
} from "./combobox-utils";
import { comboboxReducer, createInitialState } from "./use-combobox-reducer";

/**
 * Sentinel value to prevent cmdk from auto-selecting the first item.
 * cmdk auto-selects when value is falsy, so this truthy value that
 * matches no real option prevents any highlight on open.
 */
const NO_HIGHLIGHT = "__no_highlight__";

const preventDefault = (e: { preventDefault: () => void }) => e.preventDefault();

/**
 * Bridge component rendered inside <Command> to read cmdk's internal
 * selectedItemId via useCommandState (requires Command context).
 * Reports the DOM id of the highlighted item for aria-activedescendant.
 */
function ActiveDescendantBridge({ onIdChange }: { onIdChange: (id: string | undefined) => void }) {
  const selectedItemId = useCommandState((state) => state.selectedItemId);
  useEffect(() => {
    onIdChange(selectedItemId);
  }, [selectedItemId, onIdChange]);
  return null;
}

export interface ComboboxOption {
  /** Arbitrary payload passed back to `renderOption` for rich item rendering. */
  data?: unknown;
  /** When true, the option is rendered but cannot be selected. */
  disabled?: boolean | undefined;
  group?: string | undefined;
  groupTestId?: string | undefined;
  label: string;
  testId?: string | undefined;
  value: string;
}

export interface ComboboxProps
  extends SharedProps,
    Pick<PortalRootProps, "defaultOpen">,
    Pick<PortalContentProps, "container"> {
  /** @deprecated No longer used. The combobox now uses list-based navigation. Will be removed in next major version. */
  autocomplete?: boolean | undefined;
  className?: string | undefined;
  /** @default true - Show a clear (X) button when a value is selected */
  clearable?: boolean | undefined;
  /** If true, the combobox will allow the user to create a new option */
  creatable?: boolean | undefined;
  /** Noun used in the create prompt (e.g. "option", "context"). @default "option" */
  createLabel?: string | undefined;
  disabled?: boolean | undefined;
  /**
   * Override the default "No options found." empty state. Ignored when
   * `loading` is true.
   */
  emptyState?: React.ReactNode | undefined;
  id?: string | undefined;
  inputTestId?: string | undefined;
  /**
   * When true, an inline spinner is rendered inside the popover and the
   * default "No options found." empty state is suppressed. Useful while
   * async options are being fetched.
   */
  loading?: boolean | undefined;
  onChange: (value: string) => void;
  onClose?: (() => void) | undefined;
  /** Callback function to create a new option */
  onCreateOption?: ((value: string) => void) | undefined;
  /**
   * Called on every keystroke with the current input text. Use to drive an
   * async/remote search; typically paired with a debounced fetch that
   * updates `options`.
   */
  onInputValueChange?: ((value: string) => void) | undefined;
  onOpen?: (() => void) | undefined;
  options: ComboboxOption[];
  placeholder?: string | undefined;
  preventAutoFocusOnOpen?: boolean | undefined;
  /**
   * Override the rendering of each option row. Defaults to rendering the
   * option label. The active check icon is still rendered by the component.
   */
  renderOption?: ((option: ComboboxOption) => React.ReactNode) | undefined;
  /** Content for the start slot of the input. Defaults to a search icon. Pass `null` to hide. */
  start?: React.ReactNode | null;
  value?: string | undefined;
}

const DEFAULT_START = <Search className="opacity-50" size={15} />;

export const Combobox = memo(
  ({
    options,
    value: controlledValue = "",
    onChange,
    placeholder,
    disabled,
    creatable,
    onCreateOption,
    createLabel = "option",
    start = DEFAULT_START,
    clearable = true,
    className,
    onOpen,
    onClose,
    container,
    testId,
    defaultOpen = false,
    preventAutoFocusOnOpen = false,
    inputTestId,
    id,
    onInputValueChange,
    loading = false,
    emptyState,
    renderOption,
  }: ComboboxProps) => {
    "use no memo";

    const [state, dispatch] = useReducer(comboboxReducer, { controlledValue, defaultOpen, options }, (init) =>
      createInitialState(init.options, init.controlledValue, init.defaultOpen)
    );
    const { open, inputValue, highlightedValue, activeDescendantId, userHasTyped } = state;

    const inputRef = useRef<HTMLInputElement>(null);
    const listId = useId();
    const hasStart = start !== null && start !== undefined;

    // Derived values (pure computations)
    const controlledLabel = useMemo(() => resolveLabel(options, controlledValue), [controlledValue, options]);
    const filteredOptions = useMemo(
      () => filterOptions(options, inputValue, controlledLabel),
      [options, inputValue, controlledLabel]
    );
    const groupedOptions = useMemo(() => groupOptions(filteredOptions), [filteredOptions]);
    const canCreate =
      Boolean(creatable) && inputValue.trim().length > 0 && !options.some((option) => option.value === inputValue);
    const navigableValues = useMemo(
      () => getNavigableValues(filteredOptions, canCreate, inputValue),
      [filteredOptions, canCreate, inputValue]
    );
    const showClearButton = clearable && controlledValue && !disabled;

    // ── Effects (genuine side effects only) ───────────────────────────

    // Sync inputValue when controlled value changes externally
    useEffect(() => {
      dispatch({ controlledLabel, type: "SYNC_CONTROLLED" });
    }, [controlledLabel]);

    // Focus input when popover opens
    useEffect(() => {
      if (!(inputRef.current && open && !preventAutoFocusOnOpen)) {
        return;
      }
      const timer = setTimeout(() => {
        if (inputRef.current) {
          inputRef.current.focus();
          const { length } = inputRef.current.value;
          inputRef.current.setSelectionRange(length, length);
        }
      }, 0);
      return () => clearTimeout(timer);
    }, [open, preventAutoFocusOnOpen]);

    // Fire onOpen/onClose callbacks (single-concern: only callbacks)
    const prevOpenRef = useRef(open);
    useEffect(() => {
      if (prevOpenRef.current !== open) {
        if (open) {
          onOpen?.();
        } else {
          onClose?.();
        }
        prevOpenRef.current = open;
      }
    }, [open, onOpen, onClose]);

    // ── Handlers ──────────────────────────────────────────────────────

    const handleActiveDescendantChange = useCallback(
      (descendantId: string | undefined) => dispatch({ id: descendantId, type: "SET_ACTIVE_DESCENDANT" }),
      []
    );

    const handleHighlightChange = useCallback(
      (value: string) => dispatch({ nextHighlight: value, type: "NAVIGATE" }),
      []
    );

    const selectOption = useCallback(
      (option: ComboboxOption) => {
        if (option.disabled) {
          return;
        }
        if (controlledValue === option.value) {
          onChange("");
          dispatch({ type: "TOGGLE_OFF" });
        } else {
          onChange(option.value);
          dispatch({ label: option.label, type: "SELECT" });
        }
      },
      [onChange, controlledValue]
    );

    const handleCreatableSubmit = useCallback(() => {
      onChange(inputValue);
      dispatch({ inputValue, type: "CREATE_SUBMIT" });
      onCreateOption?.(inputValue);
    }, [inputValue, onChange, onCreateOption]);

    const handleClear = useCallback(
      (e: React.MouseEvent) => {
        e.stopPropagation();
        onChange("");
        dispatch({ type: "CLEAR" });
        inputRef.current?.focus();
      },
      [onChange]
    );

    const handlePopoverOpenChange = useCallback(
      (newOpen: boolean) => {
        if (disabled) {
          return;
        }
        dispatch(newOpen ? { type: "OPEN" } : { type: "CLOSE" });
      },
      [disabled]
    );

    const handleInputChange = useCallback(
      (e: React.ChangeEvent<HTMLInputElement>) => {
        const newValue = e.target.value;
        dispatch({ firstMatch: findFirstMatch(options, newValue), type: "TYPE", value: newValue });
        onInputValueChange?.(newValue);
      },
      [options, onInputValueChange]
    );

    const handleInputClick = useCallback(() => {
      if (!open) {
        dispatch({ type: "INPUT_CLICK" });
      }
    }, [open]);

    const handleComboboxInputBlur = useCallback(() => {
      if (inputValue.trim() === "" && controlledValue && userHasTyped) {
        onChange("");
        dispatch({ type: "BLUR_CLEAR" });
      } else if (inputValue !== controlledLabel) {
        const matchesOption = options.some((opt) => opt.value === inputValue || opt.label === inputValue);
        if (!creatable || (!matchesOption && inputValue.trim() === "")) {
          dispatch({ controlledLabel, type: "BLUR_REVERT" });
        }
      }
    }, [inputValue, controlledValue, controlledLabel, options, creatable, onChange, userHasTyped]);

    // ── Keyboard handlers (decomposed per key) ────────────────────────

    const handleArrowKey = useCallback(
      (event: React.KeyboardEvent, direction: 1 | -1) => {
        event.preventDefault();
        if (!open) {
          dispatch({ type: "ARROW_OPEN" });
          return;
        }
        dispatch({
          nextHighlight: computeNextHighlight(navigableValues, highlightedValue, direction),
          type: "NAVIGATE",
        });
      },
      [open, navigableValues, highlightedValue]
    );

    const handleEnterKey = useCallback(
      (event: React.KeyboardEvent) => {
        if (!open) {
          return; // Let Enter propagate to form when closed
        }
        event.preventDefault();
        event.stopPropagation();

        const isCreateHighlighted = highlightedValue.toLowerCase().startsWith(CREATE_ITEM_PREFIX.toLowerCase());

        if (isCreateHighlighted && canCreate) {
          handleCreatableSubmit();
        } else {
          const option = filteredOptions.find((o) => o.label.toLowerCase() === highlightedValue.toLowerCase());
          if (option) {
            selectOption(option);
          } else if (inputValue.trim() === "" && controlledValue) {
            onChange("");
            dispatch({ type: "ENTER_CLEAR" });
          } else if (creatable && canCreate) {
            handleCreatableSubmit();
          } else {
            dispatch({ controlledLabel, type: "ENTER_REVERT" });
          }
        }
      },
      [
        open,
        highlightedValue,
        canCreate,
        handleCreatableSubmit,
        filteredOptions,
        selectOption,
        inputValue,
        controlledValue,
        controlledLabel,
        onChange,
        creatable,
      ]
    );

    const handleEscapeKey = useCallback(
      (event: React.KeyboardEvent) => {
        if (open) {
          event.preventDefault();
          dispatch({ type: "CLOSE" });
        } else if (controlledValue) {
          event.preventDefault();
          event.stopPropagation();
          onChange("");
          dispatch({ type: "ESCAPE_CLEAR" });
        }
      },
      [open, controlledValue, onChange]
    );

    const handleArrowRightKey = useCallback(
      (event: React.KeyboardEvent) => {
        const input = inputRef.current;
        if (input && input.selectionStart === input.value.length && open && highlightedValue) {
          const option = filteredOptions.find((o) => o.label.toLowerCase() === highlightedValue.toLowerCase());
          if (option) {
            event.preventDefault();
            selectOption(option);
          }
        }
      },
      [open, highlightedValue, filteredOptions, selectOption]
    );

    const handleKeyDown = useCallback(
      (event: React.KeyboardEvent<HTMLInputElement>) => {
        switch (event.key) {
          case "ArrowDown":
            return handleArrowKey(event, 1);
          case "ArrowUp":
            return handleArrowKey(event, -1);
          case "Enter":
            return handleEnterKey(event);
          case "Escape":
            return handleEscapeKey(event);
          case "ArrowRight":
            return handleArrowRightKey(event);
          default:
            return;
        }
      },
      [handleArrowKey, handleEnterKey, handleEscapeKey, handleArrowRightKey]
    );

    // ── Memoized props ────────────────────────────────────────────────

    const popoverStyle = useMemo(
      () => ({ width: inputRef.current?.clientWidth }),
      // Recalculate when open changes (ref width may have changed)
      []
    );

    // ── Render ────────────────────────────────────────────────────────

    return (
      <Popover onOpenChange={handlePopoverOpenChange} open={open} testId={testId}>
        <PopoverTrigger asChild nativeButton={false}>
          <Input
            aria-activedescendant={open ? activeDescendantId : undefined}
            aria-autocomplete="list"
            aria-controls={listId}
            aria-expanded={open}
            autoComplete="off"
            autoCorrect="off"
            className="relative w-full shadow-none"
            containerClassName={className}
            disabled={disabled}
            id={id}
            onBlur={handleComboboxInputBlur}
            onChange={handleInputChange}
            onClick={handleInputClick}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            ref={inputRef}
            role="combobox"
            spellCheck={false}
            testId={inputTestId}
            type="text"
            value={inputValue}
          >
            {hasStart ? <InputStart>{start}</InputStart> : null}
            <InputEnd>
              {showClearButton ? (
                <Button
                  aria-label="Clear selection"
                  className="pointer-events-auto size-auto rounded-sm p-0 opacity-50 hover:bg-transparent hover:opacity-100"
                  onClick={handleClear}
                  onMouseDown={preventDefault}
                  size="icon-xs"
                  tabIndex={-1}
                  type="button"
                  variant="ghost"
                >
                  <X size={15} />
                </Button>
              ) : null}
              <ChevronsUpDown className="opacity-50" size={15} />
            </InputEnd>
          </Input>
        </PopoverTrigger>
        <PopoverContent
          className="p-0"
          container={container}
          initialFocus={preventAutoFocusOnOpen ? false : undefined}
          onMouseDown={preventDefault}
          style={popoverStyle}
        >
          <Command
            loop
            onValueChange={handleHighlightChange}
            shouldFilter={false}
            size="full"
            value={highlightedValue || NO_HIGHLIGHT}
            variant="minimal"
          >
            <ActiveDescendantBridge onIdChange={handleActiveDescendantChange} />
            <CommandList id={listId}>
              {loading ? (
                <div
                  aria-busy="true"
                  className="flex items-center gap-2 px-3 py-4 text-muted-foreground text-sm"
                  role="status"
                >
                  <Spinner className="size-4" />
                  <span>Loading…</span>
                </div>
              ) : (
                <CommandEmpty>{emptyState ?? "No options found."}</CommandEmpty>
              )}
              {(groupedOptions ?? [{ heading: "", options: filteredOptions }]).map((group) => (
                <CommandGroup
                  heading={group.heading || undefined}
                  key={group.heading || "default"}
                  testId={group.testId}
                >
                  {group.options.map((option) => (
                    <CommandItem
                      disabled={option.disabled ?? false}
                      key={option.value}
                      onSelect={() => selectOption(option)}
                      testId={option.testId}
                      value={option.label}
                    >
                      {renderOption ? renderOption(option) : option.label}
                      <Check
                        className={cn("ml-auto", controlledValue === option.value ? "opacity-100" : "opacity-0")}
                      />
                    </CommandItem>
                  ))}
                </CommandGroup>
              ))}
              {canCreate ? (
                <CommandGroup>
                  <CommandItem forceMount onSelect={handleCreatableSubmit} value={`${CREATE_ITEM_PREFIX}${inputValue}`}>
                    <Plus className="size-4 shrink-0" />
                    <span className="truncate">Create &quot;{inputValue}&quot;</span>
                  </CommandItem>
                </CommandGroup>
              ) : null}
              {creatable && !canCreate ? (
                <CommandGroup>
                  <CommandItem disabled forceMount value="__create_prompt__">
                    <Plus className="size-4 shrink-0 opacity-50" />
                    <span className="truncate text-muted-foreground">Type to create a new {createLabel}...</span>
                  </CommandItem>
                </CommandGroup>
              ) : null}
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    );
  }
);
Combobox.displayName = "Combobox";

import type { ComboboxOption } from ".";
import { resolveLabel } from "./combobox-utils";

// ── State ─────────────────────────────────────────────────────────────
// Readonly at every level — the reducer MUST return a new object.
export type ComboboxState = Readonly<{
  open: boolean;
  inputValue: string;
  highlightedValue: string;
  activeDescendantId: string | undefined;
  userHasTyped: boolean;
}>;

// ── Actions (discriminated union) ─────────────────────────────────────
// Each variant carries only the payload it needs. TypeScript narrows
// the type inside each switch case, so `action.value` is only available
// on variants that declare it.
export type ComboboxAction =
  // Popover lifecycle
  | { readonly type: "OPEN" }
  | { readonly type: "CLOSE" }
  | { readonly type: "ARROW_OPEN" }

  // User input
  | { readonly type: "INPUT_CLICK" }
  | { readonly type: "TYPE"; readonly value: string; readonly firstMatch: string }

  // Selection
  | { readonly type: "SELECT"; readonly label: string }
  | { readonly type: "TOGGLE_OFF" }
  | { readonly type: "CLEAR" }
  | { readonly type: "CREATE_SUBMIT"; readonly inputValue: string }

  // Keyboard navigation
  | { readonly type: "NAVIGATE"; readonly nextHighlight: string }

  // Enter key variants (each has distinct state transition)
  | { readonly type: "ENTER_REVERT"; readonly controlledLabel: string }
  | { readonly type: "ENTER_CLEAR" }

  // Escape
  | { readonly type: "ESCAPE_CLEAR" }

  // Blur
  | { readonly type: "BLUR_CLEAR" }
  | { readonly type: "BLUR_REVERT"; readonly controlledLabel: string }

  // External sync
  | { readonly type: "SYNC_CONTROLLED"; readonly controlledLabel: string }

  // cmdk bridge
  | { readonly type: "SET_ACTIVE_DESCENDANT"; readonly id: string | undefined };

// ── Exhaustive check helper ───────────────────────────────────────────
// If a new action variant is added to the union but not handled in the
// switch, TypeScript will error: "Argument of type '...' is not
// assignable to parameter of type 'never'."
const assertNever = (action: never): never => {
  throw new Error(`Unhandled combobox action: ${(action as ComboboxAction).type}`);
};

// ── Reducer (pure function — no React imports, no side effects) ───────
export const comboboxReducer = (state: ComboboxState, action: ComboboxAction): ComboboxState => {
  switch (action.type) {
    case "OPEN":
      return { ...state, highlightedValue: "", open: true, userHasTyped: false };
    case "CLOSE":
      return { ...state, activeDescendantId: undefined, highlightedValue: "", open: false };
    case "ARROW_OPEN":
      return { ...state, open: true };
    case "INPUT_CLICK":
      return { ...state, inputValue: "", open: true, userHasTyped: false };
    case "TYPE":
      return {
        ...state,
        highlightedValue: action.firstMatch,
        inputValue: action.value,
        open: true,
        userHasTyped: true,
      };
    case "SELECT":
      return { ...state, inputValue: action.label, open: false };
    case "TOGGLE_OFF":
      return { ...state, inputValue: "", open: false };
    case "CLEAR":
      return { ...state, inputValue: "" };
    case "CREATE_SUBMIT":
      return { ...state, inputValue: action.inputValue, open: false };
    case "NAVIGATE":
      return { ...state, highlightedValue: action.nextHighlight };
    case "ENTER_REVERT":
      return { ...state, inputValue: action.controlledLabel, open: false };
    case "ENTER_CLEAR":
      return { ...state, inputValue: "", open: false };
    case "ESCAPE_CLEAR":
      return { ...state, inputValue: "" };
    case "BLUR_CLEAR":
      return { ...state, inputValue: "", userHasTyped: false };
    case "BLUR_REVERT":
      return { ...state, inputValue: action.controlledLabel, userHasTyped: false };
    case "SYNC_CONTROLLED":
      if (state.inputValue === action.controlledLabel) {
        return state;
      }
      return { ...state, inputValue: action.controlledLabel };
    case "SET_ACTIVE_DESCENDANT":
      return { ...state, activeDescendantId: action.id };
    default:
      return assertNever(action);
  }
};

// ── Initial state factory ─────────────────────────────────────────────
export const createInitialState = (
  options: readonly ComboboxOption[],
  controlledValue: string,
  defaultOpen: boolean
): ComboboxState => ({
  activeDescendantId: undefined,
  highlightedValue: "",
  inputValue: resolveLabel(options, controlledValue),
  open: defaultOpen,
  userHasTyped: false,
});

import { cva, type VariantProps } from "class-variance-authority";
import { Command as CommandPrimitive } from "cmdk";
import { ChevronRight, SearchIcon } from "lucide-react";
import React from "react";

import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Popover, PopoverAnchor, PopoverContent } from "@/components/ui/popover";
import { Text } from "@/components/ui/typography";
import { cn, type FixedPositionContentProps, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

const commandVariants = cva("flex size-full flex-col overflow-hidden rounded-md bg-popover text-popover-foreground", {
  defaultVariants: {
    size: "md",
    variant: "elevated",
  },
  variants: {
    size: {
      full: "w-full",
      lg: "min-w-[500px] max-w-2xl",
      md: "min-w-[400px] max-w-lg md:min-w-[450px]",
      sm: "min-w-[300px] max-w-sm",
    },
    variant: {
      dialog: "",
      elevated: "!border-input border shadow-md",
      minimal: "",
    },
  },
});

interface CommandProps
  extends React.ComponentProps<typeof CommandPrimitive>,
    VariantProps<typeof commandVariants>,
    SharedProps {}

function Command({ className, variant, size, testId, ...props }: CommandProps) {
  return (
    <CommandPrimitive
      className={cn(commandVariants({ size, variant }), className)}
      data-slot="command"
      data-testid={testId}
      {...props}
    />
  );
}

type CommandDialogProps = Omit<React.ComponentProps<typeof Dialog>, "children"> &
