);

MultiSelectContent.displayName = "MultiSelectContent";

type MultiSelectItemProps = React.ComponentPropsWithoutRef<typeof CommandItem> &
  Partial<MultiSelectOptionItem> &
  SharedProps & {
    onSelect?: (value: string, item: MultiSelectOptionItem) => void;
    onDeselect?: (value: string, item: MultiSelectOptionItem) => void;
  };

const MultiSelectItem = React.forwardRef<React.ComponentRef<typeof CommandItem>, MultiSelectItemProps>(
  (
    {
      value,
      onSelect: onSelectProp,
      onDeselect: onDeselectProp,
      children,
      label,
      disabled: disabledProp,
      className,
      selectedTestId,
      testId,
      ...props
    },
    forwardedRef
  ) => {
    const { value: contextValue, maxCount, onSelect, onDeselect, itemCache } = useMultiSelect();

    const item = value
      ? {
          label: label || (typeof children === "string" ? children : undefined),
          selectedTestId,
          testId,
          value,
        }
      : undefined;

    const selected = Boolean(value && contextValue.includes(value));

    React.useEffect(
      function cacheItemMetadata() {
        if (value) {
          itemCache.set(value, {
            label: label || (typeof children === "string" ? children : undefined),
            selectedTestId,
            testId,
            value,
          });
        }
      },
      [children, itemCache, label, selectedTestId, testId, value]
    );

    const disabled = Boolean(disabledProp || (!selected && maxCount && contextValue.length >= maxCount));

    const handleClick = () => {
      if (!(value && item)) {
        return;
      }
      if (selected) {
        onDeselectProp?.(value, item);
        onDeselect(value, item);
      } else {
        itemCache.set(value, item);
        onSelectProp?.(value, item);
        onSelect(value, item);
      }
    };

    let labelText: string | undefined;
    if (typeof label === "string") {
      labelText = label;
    } else if (typeof children === "string") {
      labelText = children;
    }
    const keywords = labelText && labelText !== value ? [labelText] : undefined;

    return (
      <CommandItem
        {...props}
        className={cn(disabled && "cursor-not-allowed text-muted-foreground", className)}
        disabled={disabled}
        {...(keywords ? { keywords } : {})}
        {...(!disabled && value ? { onSelect: handleClick } : {})}
        ref={forwardedRef}
        testId={testId}
        {...(value === undefined ? {} : { value })}
      >
        <span className="mr-2 truncate">{children || label || value}</span>
        {selected ? <Check className="ml-auto size-4 shrink-0" /> : null}
      </CommandItem>
    );
  }
);

MultiSelectItem.displayName = "MultiSelectItem";

const MultiSelectGroup = React.forwardRef<
  React.ComponentRef<typeof CommandGroup>,
  React.ComponentPropsWithoutRef<typeof CommandGroup> & SharedProps
>(({ testId, ...props }, forwardRef) => <CommandGroup {...props} ref={forwardRef} testId={testId} />);

MultiSelectGroup.displayName = "MultiSelectGroup";

const MultiSelectSeparator = React.forwardRef<
  React.ComponentRef<typeof CommandSeparator>,
  React.ComponentPropsWithoutRef<typeof CommandSeparator>
>((props, forwardRef) => <CommandSeparator {...props} ref={forwardRef} />);

MultiSelectSeparator.displayName = "MultiSelectSeparator";

const MultiSelectEmpty = React.forwardRef<
  React.ComponentRef<typeof CommandEmpty>,
  React.ComponentPropsWithoutRef<typeof CommandEmpty>
>(({ children = "No Content", ...props }, forwardRef) => (
  <CommandEmpty {...props} ref={forwardRef}>
    {children}
  </CommandEmpty>
));

MultiSelectEmpty.displayName = "MultiSelectEmpty";

export interface MultiSelectOptionSeparator {
  key: string;
  type: "separator";
}

export interface MultiSelectOptionGroup {
  children: MultiSelectOption[];
  heading?: React.ReactNode | undefined;
  key: string;
  testId?: string | undefined;
  value?: string | undefined;
}

export type MultiSelectOption =
  | Pick<MultiSelectItemProps, "value" | "label" | "disabled" | "onSelect" | "onDeselect" | "selectedTestId" | "testId">
  | MultiSelectOptionSeparator
  | MultiSelectOptionGroup;

function findMultiSelectOption(
  options: MultiSelectOption[] | undefined,
  value: string
): MultiSelectOptionItem | undefined {
  for (const option of options ?? []) {
    if ("type" in option) {
      continue;
    }
    if ("children" in option) {
      const item = findMultiSelectOption(option.children, value);
      if (item) {
        return item;
      }
      continue;
    }
    if (option.value === value) {
      return {
        label: option.label,
        selectedTestId: option.selectedTestId,
        testId: option.testId,
        value,
      };
    }
  }
  return;
}

function renderMultiSelectOptions(list: MultiSelectOption[]) {
  return list.map((option) => {
    if ("type" in option) {
      if (option.type === "separator") {
        return <MultiSelectSeparator key={option.key} />;
      }

      return null;
    }

    if ("children" in option) {
      return (
        <MultiSelectGroup
          heading={option.heading}
          key={option.key}
          testId={option.testId}
          {...(option.value === undefined ? {} : { value: option.value })}
        >
          {renderMultiSelectOptions(option.children)}
        </MultiSelectGroup>
      );
    }

    return (
      <MultiSelectItem key={option.value} {...option} testId={option.testId}>
        {option.label}
      </MultiSelectItem>
    );
  });
}

// Simplified API for backend developers
type SimpleMultiSelectProps = PortalRootProps &
  SharedProps &
  Pick<PortalContentProps, "container" | "onOpenAutoFocus"> & {
    id?: string;
    options: MultiSelectOption[] | string[];
    value?: string[];
    onValueChange?: (value: string[]) => void;
    placeholder?: string;
    className?: string;
    disabled?: boolean;
    maxCount?: number;
    maxDisplay?: number;
    searchable?: boolean;
    width?: "sm" | "md" | "lg" | "xl" | "full" | "auto";
  };

const widthClasses = {
  auto: "w-auto",
  full: "w-full",
  lg: "w-80",
  md: "w-64",
  sm: "w-48",
  xl: "w-96",
};

function SimpleMultiSelect({
  id,
  options,
  value,
  onValueChange,
  placeholder = "Select items...",
  className,
  disabled,
  maxCount,
  maxDisplay,
  searchable = true,
  width = "md",
  container,
  open,
  defaultOpen,
  onOpenChange,
  testId,
}: SimpleMultiSelectProps) {
  // Convert simple string array to option objects
  const normalizedOptions: MultiSelectOption[] = React.useMemo(
    () =>
      options.map((option) => {
        if (typeof option === "string") {
          return { label: option, value: option };
        }
        return option;
      }),
    [options]
  );

  return (
    <MultiSelect
      defaultOpen={defaultOpen}
      disabled={disabled}
      maxCount={maxCount}
      onOpenChange={onOpenChange}
      onValueChange={onValueChange}
      open={open}
      testId={testId}
      value={value}
    >
      <MultiSelectTrigger
        className={cn(widthClasses[width], className)}
        id={id}
        testId={testId ? `${testId}-control` : undefined}
      >
        <MultiSelectValue
          maxDisplay={maxDisplay}
          options={normalizedOptions}
          placeholder={placeholder}
          testId={testId}
        />
      </MultiSelectTrigger>
      <MultiSelectContent container={container} testId={testId ? `${testId}-content` : undefined}>
        {searchable ? (
          <MultiSelectSearch placeholder="Search…" testId={testId ? `${testId}-search` : undefined} />
        ) : null}
        <MultiSelectList>{renderMultiSelectOptions(normalizedOptions)}</MultiSelectList>
        <MultiSelectEmpty>No items found</MultiSelectEmpty>
      </MultiSelectContent>
    </MultiSelect>
  );
}

export {
  MultiSelect,
  MultiSelectContent,
  MultiSelectEmpty,
  MultiSelectGroup,
  MultiSelectItem,
  MultiSelectList,
  MultiSelectSearch,
  MultiSelectSeparator,
  MultiSelectTrigger,
  MultiSelectValue,
  renderMultiSelectOptions,
  SimpleMultiSelect,
};

"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { AnimatePresence, type HTMLMotionProps, motion, type Transition } from "motion/react";
import React from "react";

import { usePortalContainer } from "@/registry/base-nova/protoform/hooks/use-portal-container";
import {
  asChildTrigger,
  narrowOpenChange,
  renderWithDataState,
  Slot,
  useMirroredOpen,
} from "@/registry/base-nova/protoform/lib/base-ui-compat";
import { cn, type PortalContentProps, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

interface PopoverContextType {
  isOpen: boolean;
}

const PopoverContext = React.createContext<PopoverContextType | undefined>(undefined);

const usePopover = (): PopoverContextType => {
  const context = React.useContext(PopoverContext);
  if (!context) {
    throw new Error("usePopover must be used within a Popover");
  }
  return context;
};

interface PopoverAnchorContextType {
  anchorRef: React.RefObject<Element | null>;
  hasAnchor: boolean;
  setHasAnchor: (hasAnchor: boolean) => void;
}

const PopoverAnchorContext = React.createContext<PopoverAnchorContextType | undefined>(undefined);

type Side = "top" | "bottom" | "left" | "right";
type Align = "start" | "center" | "end";

const getInitialPosition = (side: Side) => {
  switch (side) {
    case "top":
      return { y: 15 };
    case "bottom":
      return { y: -15 };
    case "left":
      return { x: 15 };
    case "right":
      return { x: -15 };
    default:
      return {};
  }
};

type PopoverProps = Omit<React.ComponentProps<typeof PopoverPrimitive.Root>, "onOpenChange" | "children"> &
  SharedProps & {
    onOpenChange?: (open: boolean) => void;
    children?: React.ReactNode;
  };

function Popover({ children, testId, onOpenChange, ...props }: PopoverProps) {
  const { isOpen, handleOpenChange } = useMirroredOpen(props.open, props.defaultOpen, onOpenChange);
  const anchorRef = React.useRef<Element | null>(null);
  const [hasAnchor, setHasAnchor] = React.useState(false);

  const anchorCtx = React.useMemo<PopoverAnchorContextType>(
    () => ({ anchorRef, hasAnchor, setHasAnchor }),
    [hasAnchor]
  );
  const popoverContextValue = React.useMemo(() => ({ isOpen }), [isOpen]);

  return (
    <PopoverContext.Provider value={popoverContextValue}>
      <PopoverAnchorContext.Provider value={anchorCtx}>
        <PopoverPrimitive.Root
          data-slot="popover"
          data-testid={testId}
          {...props}
          onOpenChange={narrowOpenChange(handleOpenChange)}
        >
          {children}
        </PopoverPrimitive.Root>
      </PopoverAnchorContext.Provider>
    </PopoverContext.Provider>
  );
}

type PopoverTriggerProps = React.ComponentProps<typeof PopoverPrimitive.Trigger> &
  SharedProps & {
    asChild?: boolean;
  };

function PopoverTrigger({ className, testId, ...props }: PopoverTriggerProps) {
  return (
    <PopoverPrimitive.Trigger
      className={cn("cursor-pointer", className)}
      data-slot="popover-trigger"
      data-testid={testId}
      {...asChildTrigger(props)}
    />
  );
}

type PopoverContentProps = React.ComponentProps<typeof PopoverPrimitive.Popup> &
  HTMLMotionProps<"div"> &
  SharedProps &
  Pick<PortalContentProps, "container" | "onOpenAutoFocus"> & {
    transition?: Transition;
    side?: Side;
    align?: Align;
    sideOffset?: number;
    alignOffset?: number;
  };

function PopoverContent(contentProps: PopoverContentProps) {
  const {
    className,
    align = "center",
    side = "bottom",
    sideOffset = 4,
    alignOffset,
    transition = { damping: 25, stiffness: 300, type: "spring" },
    children,
    testId,
    container,
    ...props
  } = contentProps;
  Reflect.deleteProperty(props, "onOpenAutoFocus");
  const { isOpen } = usePopover();
  const initialPosition = getInitialPosition(side);
  const portalContainer = usePortalContainer();
  const anchorCtx = React.useContext(PopoverAnchorContext);

  return (
    <AnimatePresence>
      {isOpen ? (
        <PopoverPrimitive.Portal container={container ?? portalContainer} data-slot="popover-portal" keepMounted>
          <PopoverPrimitive.Positioner
            align={align}
            alignOffset={alignOffset}
            {...(anchorCtx?.hasAnchor && anchorCtx.anchorRef.current ? { anchor: anchorCtx.anchorRef } : {})}
            className="z-50"
            side={side}
            sideOffset={sideOffset}
          >
            <PopoverPrimitive.Popup render={renderWithDataState("div")} {...props}>
              <motion.div
                animate={{ opacity: 1, scale: 1, x: 0, y: 0 }}
                className={cn(
                  "!border-input w-72 rounded-lg border bg-popover p-4 text-popover-foreground shadow-md outline-none",
                  className
                )}
                data-slot="popover-content"
                data-testid={testId}
                exit={{ opacity: 0, scale: 0.5, ...initialPosition }}
                initial={{ opacity: 0, scale: 0.5, ...initialPosition }}
                key="popover-content"
                transition={transition}
              >
                {children}
              </motion.div>
            </PopoverPrimitive.Popup>
          </PopoverPrimitive.Positioner>
        </PopoverPrimitive.Portal>
      ) : null}
    </AnimatePresence>
  );
}

interface PopoverAnchorProps {
  asChild?: boolean;
  children?: React.ReactNode;
  render?: React.ReactElement;
}

function PopoverAnchor({ asChild, children, render }: PopoverAnchorProps) {
  "use no memo";

  const ctx = React.useContext(PopoverAnchorContext);

  const setRef = React.useCallback(
    (node: Element | null) => {
      if (ctx) {
        ctx.anchorRef.current = node;
        ctx.setHasAnchor(Boolean(node));
      }
    },
    [ctx]
  );

  const renderedChild = render && children !== undefined ? React.cloneElement(render, undefined, children) : render;
  const child = renderedChild ?? (asChild && React.isValidElement(children) ? children : undefined);

  if (child) {
    return (
      <Slot data-slot="popover-anchor" ref={setRef as React.Ref<HTMLElement>}>
        {child}
      </Slot>
    );
  }

  return (
    <div data-slot="popover-anchor" ref={setRef as React.Ref<HTMLDivElement>}>
      {children}
    </div>
  );
}

export {
  Popover,
  PopoverAnchor,
  type PopoverAnchorProps,
  PopoverContent,
  type PopoverContentProps,
  type PopoverContextType,
  type PopoverProps,
  PopoverTrigger,
  type PopoverTriggerProps,
  usePopover,
};

import { Radio as RadioPrimitive } from "@base-ui/react/radio";
import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { Circle } from "lucide-react";
import { AnimatePresence, type HTMLMotionProps, motion, type Transition } from "motion/react";
import React from "react";

import { cn, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

// Radix RadioGroup supported an `orientation` prop; Base UI's RadioGroup does not
// declare one. Preserve the public API by accepting it and forwarding as
// `aria-orientation` + data attribute.
type RadioGroupOrientation = "vertical" | "horizontal";

type RadioGroupProps = Omit<React.ComponentProps<typeof RadioGroupPrimitive>, "onValueChange"> &
  SharedProps & {
    orientation?: RadioGroupOrientation;
    onValueChange?: (value: string) => void;
    transition?: Transition;
  };

function RadioGroup(allProps: RadioGroupProps) {
  const { className, orientation = "vertical", testId, onValueChange, ...props } = allProps;

  const handleValueChange = React.useMemo(() => {
    if (!onValueChange) {
      return;
    }
    return (next: unknown) => onValueChange(next as string);
  }, [onValueChange]);

  // Radix parity: when consumers explicitly pass `value` (controlled mode) but
  // their source-of-truth starts as `undefined` (e.g. react-hook-form
  // `field.value` before the first change), Base UI's `useControlled` warns on
  // the undefined → string transition. Radix tolerated this silently. Normalize
  // undefined → '' only when `value` was explicitly passed — uncontrolled mode
  // via `defaultValue` (without `value`) keeps working unchanged.
  const hasValueProp = "value" in allProps;
  const valueOverride = hasValueProp && allProps.value === undefined ? { value: "" } : undefined;

  return (
    <RadioGroupPrimitive
      aria-orientation={orientation}
      className={cn("grid w-full gap-2", orientation === "horizontal" && "grid-cols-2", className)}
      data-orientation={orientation}
      data-slot="radio-group"
      data-testid={testId}
      onValueChange={handleValueChange}
      {...props}
      {...valueOverride}
    />
  );
}

type RadioGroupIndicatorProps = React.ComponentProps<typeof RadioPrimitive.Indicator> & {
  transition: Transition;
};

function RadioGroupIndicator({ className, transition, ...props }: RadioGroupIndicatorProps) {
  return (
    <RadioPrimitive.Indicator
      className={cn("flex items-center justify-center data-[unchecked]:hidden", className)}
      data-slot="radio-group-indicator"
      keepMounted
      {...props}
    >
      <AnimatePresence>
        <motion.div
          animate={{ opacity: 1, scale: 1 }}
          className="flex items-center justify-center"
          data-slot="radio-group-indicator-circle"
          exit={{ opacity: 0, scale: 0.95 }}
          initial={{ opacity: 0, scale: 0.95 }}
          key="radio-group-indicator-circle"
          transition={transition}
        >
          <Circle className="size-2 fill-current stroke-none" />
        </motion.div>
      </AnimatePresence>
    </RadioPrimitive.Indicator>
  );
}

type RadioGroupItemProps = React.ComponentProps<typeof RadioPrimitive.Root> &
  HTMLMotionProps<"button"> &
  SharedProps & {
    transition?: Transition;
    variant?: "card" | "default";
  };

type MotionButtonStyle = NonNullable<HTMLMotionProps<"button">["style"]>;

function RadioGroupItem({
  children,
  className,
  transition = { duration: 0.15 },
  testId,
  variant = "default",
  ...props
}: RadioGroupItemProps) {
  return (
    <RadioPrimitive.Root
      {...(props as React.ComponentProps<typeof RadioPrimitive.Root>)}
      nativeButton
      render={(
        rootProps: React.ComponentPropsWithoutRef<"button">,
        state: { checked?: boolean; disabled?: boolean }
      ) => {
        const {
          onAnimationEnd: _onAnimationEnd,
          onAnimationStart: _onAnimationStart,
          onDrag: _onDrag,
          onDragEnd: _onDragEnd,
          onDragStart: _onDragStart,
          style,
          ...motionButtonProps
        } = rootProps;
        return (
          <motion.button
            {...motionButtonProps}
            {...(style ? { style: style as MotionButtonStyle } : {})}
            className={cn(
              variant === "card"
                ? "flex h-auto min-h-12 w-full items-center justify-between gap-4 rounded-lg border border-border/70 bg-background px-4 py-3 text-left text-foreground ring-offset-background transition-[border-color,box-shadow,background-color] hover:border-foreground/30 hover:shadow-xs focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 data-[checked]:border-foreground data-[checked]:bg-muted/30 data-[checked]:shadow-xs"
                : "!border-input relative flex aspect-square size-4 cursor-pointer items-center justify-center rounded-full border outline-none after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground dark:bg-input/30 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
              className
            )}
            data-slot="radio-group-item"
            data-state={state.checked ? "checked" : "unchecked"}
            data-testid={testId}
            {...(variant === "default" ? { whileHover: { scale: 1.05 }, whileTap: { scale: 0.95 } } : {})}
          >
            {children}
            {variant === "card" ? (
              <span
                aria-hidden="true"
                className="!border-input flex aspect-square size-5 shrink-0 items-center justify-center rounded-full border text-selected"
                data-state={state.checked ? "checked" : "unchecked"}
              >
                <RadioGroupIndicator data-slot="radio-group-item-indicator" transition={transition} />
              </span>
            ) : (
              <RadioGroupIndicator data-slot="radio-group-item-indicator" transition={transition} />
            )}
          </motion.button>
        );
      }}
    />
  );
}

export {
  RadioGroup,
  RadioGroupIndicator,
  type RadioGroupIndicatorProps,
  RadioGroupItem,
  type RadioGroupItemProps,
  type RadioGroupProps,
};

"use client";

import { Select as SelectPrimitive } from "@base-ui/react/select";
import { CheckIcon, ChevronDownIcon, ChevronUpIcon } from "lucide-react";
import React from "react";

import { useGroup } from "@/components/ui/group";
import { usePortalContainer } from "@/registry/base-nova/protoform/hooks/use-portal-container";
import { narrowOpenChange, renderWithDataState } from "@/registry/base-nova/protoform/lib/base-ui-compat";
import { cn, type PortalContentProps, type SharedProps } from "@/registry/base-nova/protoform/lib/utils";

type SelectRootProps = Omit<
  React.ComponentProps<typeof SelectPrimitive.Root>,
  "defaultValue" | "onOpenChange" | "onValueChange" | "value"
> &
  SharedProps & {
    defaultValue?: string | null;
    onOpenChange?: (open: boolean) => void;
    onValueChange?: (value: string | null) => void;
    value?: string | null;
  };

// Base UI types `value` as `unknown` because `Select.Root` is generic; the
// registry pins it to `string | null`, so validate at the boundary.
function adaptSelectValueChange(
  handler: ((value: string | null) => void) | undefined
): ((value: unknown) => void) | undefined {
  if (!handler) {
    return;
  }
  return (value) => {
    if (value !== null && typeof value !== "string") {
      throw new TypeError("Select values must be strings or null.");
    }
    handler(value);
  };
}

function Select({ testId, onOpenChange, onValueChange, ...props }: SelectRootProps) {
  return (
    <SelectPrimitive.Root
      data-slot="select"
      data-testid={testId}
      onOpenChange={narrowOpenChange(onOpenChange)}
      onValueChange={adaptSelectValueChange(onValueChange)}
      {...props}
    />
  );
}

Select.displayName = "Select";

function SelectGroup({ testId, ...props }: React.ComponentProps<typeof SelectPrimitive.Group> & SharedProps) {
  return <SelectPrimitive.Group data-slot="select-group" data-testid={testId} {...props} />;
}

SelectGroup.displayName = "SelectGroup";

type SelectValueProps = Omit<React.ComponentProps<typeof SelectPrimitive.Value>, "children"> & {
  placeholder?: React.ReactNode;
  children?: React.ReactNode | ((value: unknown) => React.ReactNode);
};

// Base UI only resolves an item's label after the popup has mounted. Until then
// it stringifies the raw value, which flashes `1` instead of `Any` for
// enum-backed selects with a controlled value. Pass a render-prop child or an
// `items` map on `<Select>` to close the gap — see the `select-enum-label` demo.
function SelectValue({ placeholder, children, ...props }: SelectValueProps) {
  // Fall back to placeholder when the render-prop returns null/undefined; Base
  // UI's primitive ignores `placeholder` once `children` is set.
  if (typeof children === "function") {
    const renderValue = children;
    return (
      <SelectPrimitive.Value data-slot="select-value" placeholder={placeholder} {...props}>
        {(value: unknown) => {
          const result = renderValue(value);
          if ((result === null || result === undefined) && placeholder !== undefined) {
            return placeholder;
          }
          return result;
        }}
      </SelectPrimitive.Value>
    );
  }
  if (children !== undefined) {
    return (
      <SelectPrimitive.Value data-slot="select-value" placeholder={placeholder} {...props}>
        {children as React.ComponentProps<typeof SelectPrimitive.Value>["children"]}
      </SelectPrimitive.Value>
    );
  }
  return <SelectPrimitive.Value data-slot="select-value" placeholder={placeholder} {...props} />;
}

